function fieldHtml(x){
  const n=`f_${esc(x.id)}`,req=x.required?'required':''; if(x.type==='section')return `<div class="form-section"><h3>${esc(x.label)}</h3><p>${esc(x.description||'')}</p></div>`;
  if(x.type==='textarea')return `<label>${esc(x.label)}${x.description?`<small>${esc(x.description)}</small>`:''}<textarea name="${n}" ${req}></textarea></label>`;
  if(x.type==='select')return `<label>${esc(x.label)}<select name="${n}" ${req}><option value="">— Chọn —</option>${(x.options||[]).map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`;
  if(x.type==='radio')return `<fieldset><legend>${esc(x.label)}</legend>${(x.options||[]).map(o=>`<label class="choice"><input type="radio" name="${n}" value="${esc(o)}" ${req}> ${esc(o)}</label>`).join('')}</fieldset>`;
  if(x.type==='checkbox')return `<fieldset><legend>${esc(x.label)}</legend>${(x.options||[]).map(o=>`<label class="choice"><input type="checkbox" name="${n}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}</fieldset>`;
  if(x.type==='consent')return `<label class="consent"><input type="checkbox" name="${n}" ${req}> <span>${esc(x.label)}</span></label>`;
  if(x.type==='file')return `<label>${esc(x.label)}${x.description?`<small>${esc(x.description)}</small>`:''}<input name="${n}" type="file" ${x.accept?`accept="${esc(x.accept)}"`:''} ${req}><small class="upload-status" data-for="${esc(x.id)}"></small></label>`;
  const type=['email','date','number','tel'].includes(x.type)?x.type:(x.type==='phone'?'tel':'text');return `<label>${esc(x.label)}${x.description?`<small>${esc(x.description)}</small>`:''}<input name="${n}" type="${type}" ${req}></label>`;
}
