function adminHead(t,d,actions=''){return `<div class="admin-head"><div><span class="eyebrow">XANH MANAGEMENT</span><h1>${esc(t)}</h1><p>${esc(d)}</p></div><div class="admin-actions">${actions}</div></div>`}
function table(rows,heads){return `<div class="table"><div class="tr th" style="--cols:${heads.length}">${heads.map(h=>`<div>${h}</div>`).join('')}</div>${rows.map(r=>`<div class="tr" style="--cols:${heads.length}">${r.map(c=>`<div>${c??''}</div>`).join('')}</div>`).join('')||'<div class="empty">Chưa có dữ liệu.</div>'}</div>`}
function statusBadge(v){return `<span class="status status-${esc(v)}">${esc(v)}</span>`}
function closeModal(){state.modal?.remove();state.modal=null}
function makeModal(html,wide=false){closeModal();const wrap=document.createElement('div');wrap.className='modal';wrap.innerHTML=`<div class="modal-card ${wide?'wide':''}">${html}</div>`;document.body.append(wrap);wrap.addEventListener('click',e=>{if(e.target===wrap)closeModal()});state.modal=wrap;return wrap}

async function uploadMedia(file,meta={}){
  const fd=new FormData();fd.append('file',file);if(meta.alt_text)fd.append('alt_text',meta.alt_text);if(meta.caption)fd.append('caption',meta.caption);if(meta.credit)fd.append('credit',meta.credit);
  if(file.type.startsWith('image/')){try{const size=await new Promise((resolve,reject)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{resolve([img.naturalWidth,img.naturalHeight]);URL.revokeObjectURL(u)};img.onerror=reject;img.src=u});fd.append('width',size[0]);fd.append('height',size[1])}catch{}}
  return (await api('/api/admin/media',{method:'POST',body:fd})).item;
}
async function openMediaPicker({onSelect,imagesOnly=true,currentId=null}={}){
  let items=(await api('/api/admin/media')).items;if(imagesOnly)items=items.filter(x=>String(x.mime_type).startsWith('image/'));
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">MEDIA LIBRARY</span><h2>Chọn ảnh / tệp</h2></div><button class="icon-btn modal-close">×</button></div><div class="picker-tools"><input id="picker-search" placeholder="Tìm theo tên hoặc alt..."><label class="btn primary">＋ Tải lên<input id="picker-upload" type="file" ${imagesOnly?'accept="image/*"':''} hidden></label></div><div class="media-grid picker-grid">${items.map(x=>`<button type="button" class="media-choice ${Number(currentId)===Number(x.id)?'selected':''}" data-id="${x.id}"><span>${String(x.mime_type).startsWith('image/')?`<img src="${x.url}" alt="${esc(x.alt_text||x.filename)}" loading="lazy">`:'📄'}</span><b>${esc(x.filename)}</b><small>${esc(x.alt_text||'Chưa có alt')}</small></button>`).join('')||'<div class="empty">Chưa có media phù hợp.</div>'}</div>`,true);
  $('.modal-close',m).onclick=closeModal;
  $$('.media-choice',m).forEach(btn=>btn.onclick=()=>{const item=items.find(x=>String(x.id)===btn.dataset.id);onSelect?.(item);closeModal()});
  $('#picker-search',m).oninput=e=>{const q=e.target.value.toLowerCase();$$('.media-choice',m).forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))};
  $('#picker-upload',m).onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const item=await uploadMedia(file,{alt_text:file.name.replace(/\.[^.]+$/,'')});toast('Đã tải lên R2');onSelect?.(item);closeModal()}catch(x){toast(x.message,'error')}};
}

function personPhotoPickerHtml(item){return `<div class="photo-picker">${item?.url?`<img src="${item.url}" alt="${esc(item.alt_text||item.filename||'Ảnh chân dung')}">`:'<div class="person-ph">Ảnh</div>'}<input type="hidden" name="photo_media_id" value="${item?.id||''}"><div><button type="button" class="btn glass choose-photo">Chọn từ Media Library</button><label class="btn glass">Tải ảnh từ máy<input class="upload-photo" type="file" accept="image/*" hidden></label><button type="button" class="btn danger remove-photo">Gỡ ảnh khỏi hồ sơ</button><small>Ảnh vuông, dọc, ngang hoặc độ phân giải lớn đều được chấp nhận. Frontend tự crop bằng object-fit và focus point của media.</small></div></div>`}
