async function personEditor(person=null){
  let photo=null;if(person?.photo_media_id)photo={id:person.photo_media_id,url:person.photo_url,alt_text:person.photo_alt};
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">CON NGƯỜI XANH</span><h2>${person?'Chỉnh sửa hồ sơ':'Thêm người'}</h2></div><button class="icon-btn modal-close">×</button></div><form id="person-editor">${personPhotoPickerHtml(photo)}<div class="form-grid two"><label>Họ và tên<input name="name" value="${esc(person?.name||'')}" required></label><label>Slug<input name="slug" value="${esc(person?.slug||'')}"></label><label>Chức danh<input name="title" value="${esc(person?.title||'')}"></label><label>Nhóm vai trò<input name="role_group" value="${esc(person?.role_group||'coordination')}"></label><label class="full">Giới thiệu<textarea name="bio">${esc(person?.bio||'')}</textarea></label><label class="full">Lĩnh vực / chuyên môn<input name="expertise" value="${esc(person?.expertise||'')}"></label><label>Thứ tự<input name="sort_order" type="number" value="${Number(person?.sort_order||0)}"></label><label>Website / liên kết chính<input name="link_website" value="${esc(person?.links?.website||'')}"></label><label class="full">SEO title<input name="seo_title" value="${esc(person?.seo?.title||'')}"></label><label class="full">SEO description<textarea name="seo_description">${esc(person?.seo?.description||'')}</textarea></label><label class="choice"><input type="checkbox" name="is_public" ${person?.is_public?'checked':''}> Công khai hồ sơ</label><label class="choice"><input type="checkbox" name="allow_index" ${person?.allow_index?'checked':''}> Cho phép Google/Bing index</label></div><div class="sticky-actions"><button type="button" class="btn glass modal-close2">Hủy</button><button class="btn primary">${person?'Lưu thay đổi':'Tạo hồ sơ'}</button></div></form>`,true);
  $('.modal-close',m).onclick=$('.modal-close2',m).onclick=closeModal;
  const form=$('#person-editor',m);
  const hidden=()=>$('input[name="photo_media_id"]',form);
  $('.choose-photo',m).onclick=()=>openMediaPicker({currentId:hidden().value,onSelect:item=>{hidden().value=item.id;$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML=`<img src="${item.url}" alt="${esc(item.alt_text||item.filename)}">`}});
  $('.upload-photo',m).onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const item=await uploadMedia(f,{alt_text:form.name.value||f.name});hidden().value=item.id;$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML=`<img src="${item.url}" alt="${esc(item.alt_text||item.filename)}">`;toast('Ảnh đã tải lên R2')}catch(x){toast(x.message,'error')}};
  $('.remove-photo',m).onclick=()=>{hidden().value='';$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML='<div class="person-ph">Ảnh</div>'};
  form.oninput=()=>state.dirty=true;
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),body={name:f.get('name'),slug:f.get('slug'),title:f.get('title'),role_group:f.get('role_group'),bio:f.get('bio'),expertise:f.get('expertise'),sort_order:Number(f.get('sort_order')||0),photo_media_id:f.get('photo_media_id')?Number(f.get('photo_media_id')):null,is_public:f.has('is_public'),allow_index:f.has('allow_index'),links:{website:f.get('link_website')},seo:{title:f.get('seo_title'),description:f.get('seo_description')}};try{if(person)await api(`/api/admin/person/${person.id}`,{method:'PUT',body});else await api('/api/admin/people',{method:'POST',body});state.dirty=false;closeModal();toast('Đã lưu hồ sơ Con người Xanh');admin('people')}catch(x){toast(x.message,'error')}};
}

