async function admin(tab='dashboard'){
  if(!(await me()))return login();const allowed=roleNav[state.user.role]||[];if(!allowed.includes(tab))tab='dashboard';let body='';
  try{
    if(tab==='dashboard'){const d=await api('/api/admin/dashboard');body=adminHead('Tổng quan','Vận hành website và cộng đồng từ một nơi.')+`<div class="dash">${[['Hồ sơ cần xử lý',d.stats.pending_submissions],['Đơn cần xử lý',d.stats.pending_applications],['Nội dung nháp',d.stats.drafts],['Media',d.stats.media],['Lượt tham gia đã xác minh',d.stats.participants],['Giờ cộng đồng đã xác minh',d.stats.volunteer_hours]].map(x=>`<div><span>${x[0]}</span><strong>${fmt(x[1])}</strong></div>`).join('')}</div><h3 class="section-title">Hoạt động gần đây</h3>${table((d.recent||[]).map(a=>[date(a.created_at),esc(a.user_name||'System'),esc(a.action),esc(a.object_type)]),['Thời gian','Người dùng','Hành động','Đối tượng'])}`}
    else if(tab==='people')body=await peopleAdmin();else if(tab==='forms')body=await formsAdmin();else if(tab==='submissions')body=await submissionsAdmin();else if(tab==='media')body=await mediaAdmin();else if(['articles','projects','activities','opportunities','initiatives','resources'].includes(tab))body=await contentAdmin(tab);else if(tab==='pages')body=await pagesAdmin();else if(tab==='applications')body=await applicationsAdmin();else if(tab==='impact')body=await impactAdmin();else if(tab==='users')body=await usersAdmin();else if(tab==='audit')body=await auditAdmin();else if(tab==='contacts')body=await contactsAdmin();else if(tab==='newsletter')body=await newsletterAdmin();else if(tab==='settings')body=await settingsAdmin();
  }catch(e){if(e.status===403)body=adminHead('403 · Không có quyền',e.message)+`<div class="empty">Quyền được kiểm tra ở cả API backend, không chỉ ẩn menu.</div>`;else body=adminHead('Không thể tải',e.message)+`<div class="empty">Kiểm tra migration D1 và cấu hình binding trước khi sử dụng module này.</div>`}
  app.innerHTML=adminShell(body,tab);wireAdmin(tab);
}
