function openCommandPalette(){
  const allowed=roleNav[state.user?.role]||[];const m=makeModal(`<div class="command-palette"><input id="command-search" autofocus placeholder="Tìm module hoặc lệnh..."><div id="command-results">${allowed.map(k=>`<button data-path="/admin/${k}">${esc(labels[k])}<span>→</span></button>`).join('')}</div></div>`);const input=$('#command-search',m);input.focus();input.oninput=()=>{$$('#command-results button',m).forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(input.value.toLowerCase()))};$$('#command-results button',m).forEach(b=>b.onclick=()=>{closeModal();go(b.dataset.path)});
}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.user)openCommandPalette()}if(e.key==='Escape')closeModal()});

