function wirePublic(path){
  $('.menu')?.addEventListener('click',()=>$('.mobile-nav')?.classList.toggle('open'));
  $('#newsletter-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=await api('/api/public/newsletter',{method:'POST',body:{email:f.get('email'),preferences:f.getAll('pref')}});toast(r.message);e.target.reset()}catch(x){toast(x.message,'error')}});
  $('#contact-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=await api('/api/public/contact',{method:'POST',body:Object.fromEntries(f)});e.target.innerHTML=`<div class="success"><h2>Đã gửi liên hệ</h2><p>${esc(r.message)}</p></div>`}catch(x){toast(x.message,'error')}});
  if(path.startsWith('/tham-gia/'))$('#public-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=(await api(`/api/public/form?slug=${encodeURIComponent(path.split('/').pop())}`)).item,f=new FormData(e.target),answers={};try{for(const x of form.fields||[]){if(x.type==='section')continue;const n=`f_${x.id}`;if(x.type==='file'){const file=f.get(n);if(file&&file.size){const fd=new FormData();fd.append('form_id',form.id);fd.append('field_id',x.id);fd.append('file',file);const up=(await api('/api/public/form-upload',{method:'POST',body:fd})).upload;answers[x.id]={upload_token:up.upload_token,filename:up.filename};const st=$(`[data-for="${CSS.escape(x.id)}"]`,e.target);if(st)st.textContent='Đã tải tệp an toàn.'}continue}if(x.type==='checkbox')answers[x.id]=f.getAll(n);else if(x.type==='consent')answers[x.id]=f.has(n);else answers[x.id]=f.get(n)}const r=await api('/api/public/form-submit',{method:'POST',body:{form_id:form.id,full_name:f.get('full_name'),email:f.get('email'),phone:f.get('phone'),guardian_consent:f.has('guardian_consent'),answers}});e.target.innerHTML=`<div class="success"><h2>${esc(r.title||'Đã nhận hồ sơ')}</h2><p>${esc(r.message)}</p><p>Mã hồ sơ:</p><strong>${esc(r.code)}</strong></div>`}catch(x){toast(x.message,'error')}});
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const el=e.target,target=Number(el.dataset.count),start=performance.now();requestAnimationFrame(function tick(t){const p=Math.min(1,(t-start)/900);el.textContent=fmt(Math.round(target*(1-Math.pow(1-p,3))));if(p<1)requestAnimationFrame(tick)});io.unobserve(el)}}));$$('[data-count]').forEach(x=>io.observe(x));
}

async function route(){
  const path=location.pathname.replace(/\/$/,'')||'/';app.setAttribute('aria-busy','true');
  try{
    if(!path.startsWith('/admin')&&!['/login','/setup','/reset-password'].includes(path)){if(!state.site)state.site=await api('/api/public/site')}
    if(path==='/')app.innerHTML=await home();
    else if(path==='/gioi-thieu'||path==='/hanh-dong')app.innerHTML=await about();
    else if(path==='/con-nguoi')app.innerHTML=await people();
    else if(path.startsWith('/con-nguoi/'))app.innerHTML=await person(path.split('/').pop());
    else if(path==='/du-an')app.innerHTML=await listPage('project');else if(path.startsWith('/du-an/'))app.innerHTML=await detail('project',path.split('/').pop());
    else if(path==='/hoat-dong')app.innerHTML=await listPage('activity');else if(path.startsWith('/hoat-dong/'))app.innerHTML=await detail('activity',path.split('/').pop());
    else if(path==='/co-hoi')app.innerHTML=await listPage('opportunity');else if(path.startsWith('/co-hoi/'))app.innerHTML=await detail('opportunity',path.split('/').pop());
    else if(path==='/tai-nguyen')app.innerHTML=await listPage('resource');else if(path.startsWith('/tai-nguyen/'))app.innerHTML=await detail('resource',path.split('/').pop());
    else if(path==='/tin-tuc')app.innerHTML=await listPage('article');else if(path.startsWith('/tin-tuc/'))app.innerHTML=await detail('article',path.split('/').pop());
    else if(path==='/sang-kien')app.innerHTML=await listPage('initiative');else if(path.startsWith('/sang-kien/'))app.innerHTML=await detail('initiative',path.split('/').pop());
    else if(path==='/tham-gia')app.innerHTML=await forms();else if(path.startsWith('/tham-gia/'))app.innerHTML=await formPage(path.split('/').pop());
    else if(path==='/lien-he')app.innerHTML=contactPage();
    else if(['/quyen-rieng-tu','/dieu-khoan','/chinh-sach-du-lieu','/accessibility'].includes(path))app.innerHTML=await cmsPage(path.slice(1),path.slice(1).replaceAll('-',' '));
    else if(path==='/sitemap')app.innerHTML=await sitemapPage();
    else if(path==='/login')login();else if(path==='/setup')await setup();else if(path==='/reset-password')resetPasswordPage();
    else if(path==='/admin')await admin('dashboard');else if(path.startsWith('/admin/'))await admin(path.split('/')[2]||'dashboard');
    else {setMeta({title:'404 | Xanh Sky First',robots:'noindex,nofollow'});app.innerHTML=shell(`<section class="page-hero"><span class="eyebrow">404</span><h1>Không tìm thấy trang.</h1><p>Đường dẫn có thể đã thay đổi hoặc nội dung chưa được xuất bản.</p><a data-nav class="btn primary" href="/">Về trang chủ</a></section>`)}
    wirePublic(path);
  }catch(e){setMeta({title:'Lỗi hệ thống | Xanh Sky First',robots:'noindex,nofollow'});app.innerHTML=shell(`<section class="page-hero"><span class="eyebrow">${e.status===403?'403':'500'}</span><h1>${e.status===403?'Bạn không có quyền truy cập.':'Không thể tải nội dung.'}</h1><p>${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">Thử lại</button></section>`)}finally{app.removeAttribute('aria-busy');scrollTo(0,0)}
}

if('serviceWorker' in navigator) addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
route();
